VECT = {
 (1,1,0, 1,0,1, 0,1,0): ('H', 1, 3),   # A: right 3
 (2,0,2, 2,0,2, 2,2,2): ('H',-1, 2),   # B: left 2
 (6,0,6, 0,6,0, 0,6,0): ('V', 1, 2),   # C: down 2
 (3,3,3, 0,3,0, 3,0,3): ('H',-1, 4),   # D: left 4
}

def transform(grid):
    H=len(grid)
    # find 5
    r5=c5=None
    for r in range(H):
        for c in range(len(grid[r])):
            if grid[r][c]==5: r5,c5=r,c
    out=[[0]*7 for _ in range(H)]
    out[r5][c5-8]=5
    # collect left shapes (cols0-2) then right shapes (cols4-6), band = 3 rows starting where region nonzero
    shapes=[]
    for cols in [(0,1,2),(4,5,6)]:
        r=0
        while r<H:
            if any(grid[r][c]!=0 for c in cols):
                pat=tuple(grid[r+i][cols[0]+j] for i in range(3) for j in range(3))
                color=next(grid[r+i][cols[j]] for i in range(3) for j in range(3) if grid[r+i][cols[j]]!=0)
                shapes.append((VECT[pat], color)); r+=3
            else: r+=1
    pr,pc=r5,c5-8
    for (ax,sg,ln),color in shapes:
        sr,sc=pr+1,pc
        for k in range(ln):
            if ax=='H': r,c=sr,sc+sg*k
            else: r,c=sr+k,sc
            out[r][c]=color
        pr,pc=(r,c)
    return out

